PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS datasets(id TEXT PRIMARY KEY, name TEXT NOT NULL, crs TEXT NOT NULL, epsg INTEGER, height_type TEXT NOT NULL, height_datum TEXT, source_name TEXT, source_hash TEXT, source_key TEXT, imported_at TEXT NOT NULL, metadata TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS points(id TEXT PRIMARY KEY, dataset_id TEXT NOT NULL REFERENCES datasets(id), code TEXT NOT NULL, original_code TEXT NOT NULL, name TEXT NOT NULL DEFAULT '', north REAL NOT NULL, east REAL NOT NULL, height REAL, lon REAL NOT NULL, lat REAL NOT NULL, crs TEXT NOT NULL, epsg INTEGER NOT NULL, height_type TEXT NOT NULL, height_datum TEXT, category TEXT NOT NULL DEFAULT '', description TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '', source_row INTEGER, source_sheet TEXT, raw TEXT NOT NULL DEFAULT '{}', status TEXT NOT NULL DEFAULT '未巡查', favorite INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1, updated_at TEXT NOT NULL, deleted_at TEXT, UNIQUE(dataset_id,code));
CREATE INDEX IF NOT EXISTS points_dataset ON points(dataset_id);
CREATE TABLE IF NOT EXISTS visits(id TEXT PRIMARY KEY, point_id TEXT NOT NULL REFERENCES points(id), status TEXT NOT NULL, note TEXT NOT NULL DEFAULT '', visited_at TEXT NOT NULL, position TEXT, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS visits_point ON visits(point_id);
CREATE TABLE IF NOT EXISTS attachments(id TEXT PRIMARY KEY, point_id TEXT REFERENCES points(id), visit_id TEXT REFERENCES visits(id), object_key TEXT NOT NULL, thumb_key TEXT, filename TEXT NOT NULL, mime TEXT NOT NULL, size INTEGER NOT NULL, category TEXT NOT NULL DEFAULT '其他', captured_at TEXT, position TEXT, state TEXT NOT NULL DEFAULT 'ready', sha256 TEXT, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS attachments_point ON attachments(point_id);
CREATE TABLE IF NOT EXISTS audits(id TEXT PRIMARY KEY, point_id TEXT, action TEXT NOT NULL, before_json TEXT, after_json TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS login_attempts(ip_hash TEXT PRIMARY KEY, attempts INTEGER NOT NULL, reset_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS login_challenges(ip_hash TEXT PRIMARY KEY,challenge TEXT NOT NULL,expires INTEGER NOT NULL);

CREATE TABLE IF NOT EXISTS point_revision(id INTEGER PRIMARY KEY CHECK(id=1), generation TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 0);
INSERT OR IGNORE INTO point_revision(id,generation,revision) VALUES(1,lower(hex(randomblob(16))),0);
CREATE TRIGGER IF NOT EXISTS points_revision_insert AFTER INSERT ON points BEGIN UPDATE point_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS points_revision_update AFTER UPDATE ON points BEGIN UPDATE point_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS points_revision_delete AFTER DELETE ON points BEGIN UPDATE point_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS datasets_revision_insert AFTER INSERT ON datasets BEGIN UPDATE point_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS datasets_revision_update AFTER UPDATE ON datasets BEGIN UPDATE point_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS datasets_revision_delete AFTER DELETE ON datasets BEGIN UPDATE point_revision SET revision=revision+1 WHERE id=1; END;
CREATE INDEX IF NOT EXISTS points_code_normalized ON points(upper(trim(code))) WHERE deleted_at IS NULL;
CREATE VIEW IF NOT EXISTS measured_point_evidence AS SELECT id,dataset_id,code,north,east,lon,lat,version,json_extract(raw,'$.__survey.sourceHash') source_hash,json_extract(raw,'$.__survey.results[#-1].date') measured_on FROM points WHERE deleted_at IS NULL AND epsg IN (3826,3825) AND status NOT IN ('找不到','滅失','損壞','無法進入') AND CASE WHEN json_valid(raw) THEN (json_extract(raw,'$.__survey.version')=1 AND json_array_length(raw,'$.__survey.results')>0) OR json_extract(raw,'$.fieldCapture.quality')='measured' ELSE 0 END;
CREATE TRIGGER IF NOT EXISTS measured_presence_after_insert AFTER INSERT ON points WHEN EXISTS(SELECT 1 FROM measured_point_evidence e WHERE e.id=NEW.id) BEGIN INSERT INTO audits(id,point_id,action,before_json,after_json,created_at) SELECT lower(hex(randomblob(16))),p.id,'measurement_presence',json_object('status',p.status,'version',p.version),json_object('status','點位存在','version',p.version+1,'measurementPointId',e.id,'measurementCode',e.code,'measurementDate',e.measured_on,'sourceHash',e.source_hash),strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM points p JOIN measured_point_evidence e ON upper(trim(p.code))=upper(trim(e.code)) AND p.dataset_id<>e.dataset_id AND p.id<>e.id AND ((p.lon-e.lon)*100800)*((p.lon-e.lon)*100800)+((p.lat-e.lat)*111200)*((p.lat-e.lat)*111200)<=25 WHERE p.deleted_at IS NULL AND p.status IN ('未巡查','') AND NOT EXISTS(SELECT 1 FROM measured_point_evidence self WHERE self.id=p.id) AND 1=1 AND e.id=NEW.id;UPDATE points SET status='點位存在',version=version+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE upper(trim(points.code))=upper(trim(NEW.code)) AND points.deleted_at IS NULL AND points.status IN ('未巡查','') AND NOT EXISTS(SELECT 1 FROM measured_point_evidence self WHERE self.id=points.id) AND EXISTS(SELECT 1 FROM measured_point_evidence e WHERE e.id=NEW.id AND upper(trim(points.code))=upper(trim(e.code)) AND points.dataset_id<>e.dataset_id AND points.id<>e.id AND ((points.lon-e.lon)*100800)*((points.lon-e.lon)*100800)+((points.lat-e.lat)*111200)*((points.lat-e.lat)*111200)<=25); END;
CREATE TRIGGER IF NOT EXISTS original_presence_after_insert AFTER INSERT ON points WHEN NEW.status IN ('未巡查','') AND EXISTS(SELECT 1 FROM measured_point_evidence e WHERE upper(trim(NEW.code))=upper(trim(e.code)) AND NEW.dataset_id<>e.dataset_id AND NEW.id<>e.id AND ((NEW.lon-e.lon)*100800)*((NEW.lon-e.lon)*100800)+((NEW.lat-e.lat)*111200)*((NEW.lat-e.lat)*111200)<=25) BEGIN INSERT INTO audits(id,point_id,action,before_json,after_json,created_at) SELECT lower(hex(randomblob(16))),p.id,'measurement_presence',json_object('status',p.status,'version',p.version),json_object('status','點位存在','version',p.version+1,'measurementPointId',e.id,'measurementCode',e.code,'measurementDate',e.measured_on,'sourceHash',e.source_hash),strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM points p JOIN measured_point_evidence e ON upper(trim(p.code))=upper(trim(e.code)) AND p.dataset_id<>e.dataset_id AND p.id<>e.id AND ((p.lon-e.lon)*100800)*((p.lon-e.lon)*100800)+((p.lat-e.lat)*111200)*((p.lat-e.lat)*111200)<=25 WHERE p.deleted_at IS NULL AND p.status IN ('未巡查','') AND NOT EXISTS(SELECT 1 FROM measured_point_evidence self WHERE self.id=p.id) AND p.id=NEW.id AND 1=1 ORDER BY e.measured_on DESC,e.id LIMIT 1;UPDATE points SET status='點位存在',version=version+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id=NEW.id AND points.deleted_at IS NULL AND points.status IN ('未巡查','') AND NOT EXISTS(SELECT 1 FROM measured_point_evidence self WHERE self.id=points.id) AND EXISTS(SELECT 1 FROM measured_point_evidence e WHERE upper(trim(points.code))=upper(trim(e.code)) AND points.dataset_id<>e.dataset_id AND points.id<>e.id AND ((points.lon-e.lon)*100800)*((points.lon-e.lon)*100800)+((points.lat-e.lat)*111200)*((points.lat-e.lat)*111200)<=25); END;
CREATE TRIGGER IF NOT EXISTS measured_presence_after_revision AFTER UPDATE OF north,east,lon,lat,raw,deleted_at ON points WHEN EXISTS(SELECT 1 FROM measured_point_evidence e WHERE e.id=NEW.id) BEGIN INSERT INTO audits(id,point_id,action,before_json,after_json,created_at) SELECT lower(hex(randomblob(16))),p.id,'measurement_presence',json_object('status',p.status,'version',p.version),json_object('status','點位存在','version',p.version+1,'measurementPointId',e.id,'measurementCode',e.code,'measurementDate',e.measured_on,'sourceHash',e.source_hash),strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM points p JOIN measured_point_evidence e ON upper(trim(p.code))=upper(trim(e.code)) AND p.dataset_id<>e.dataset_id AND p.id<>e.id AND ((p.lon-e.lon)*100800)*((p.lon-e.lon)*100800)+((p.lat-e.lat)*111200)*((p.lat-e.lat)*111200)<=25 WHERE p.deleted_at IS NULL AND p.status IN ('未巡查','') AND NOT EXISTS(SELECT 1 FROM measured_point_evidence self WHERE self.id=p.id) AND 1=1 AND e.id=NEW.id;UPDATE points SET status='點位存在',version=version+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE upper(trim(points.code))=upper(trim(NEW.code)) AND points.deleted_at IS NULL AND points.status IN ('未巡查','') AND NOT EXISTS(SELECT 1 FROM measured_point_evidence self WHERE self.id=points.id) AND EXISTS(SELECT 1 FROM measured_point_evidence e WHERE e.id=NEW.id AND upper(trim(points.code))=upper(trim(e.code)) AND points.dataset_id<>e.dataset_id AND points.id<>e.id AND ((points.lon-e.lon)*100800)*((points.lon-e.lon)*100800)+((points.lat-e.lat)*111200)*((points.lat-e.lat)*111200)<=25); END;
